// LeishMan ORCID login worker (v2).
//
// Flow: the website or the CMS opens a popup on /auth/orcid?origin=<page origin>&mode=site|cms
//   -> ORCID login -> /auth/orcid/callback -> postMessage(result, <page origin>) -> popup closes.
//
// Who may log in and which folders they can read comes from ACCESS_URL (/data/access.json,
// generated by the Nuxt site from the working-group member lists). The result carries a signed
// session token (`session`) that the Nextcloud worker verifies. The GitHub token that lets the
// CMS commit is only handed to admins and editors.
//
// Secrets (wrangler secret put): ORCID_CLIENT_ID, ORCID_CLIENT_SECRET, GITHUB_BOT_TOKEN, SESSION_SECRET
// Vars (wrangler.toml): BASE_URL, FRONT_URL, ALLOWED_ORIGINS, ACCESS_URL, CONTACT_EMAIL

import { isAllowedOrigin, randomId, signSession } from "../shared/session.js";

const STATE_COOKIE = "leishman_orcid_state";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (url.pathname === "/debug") return text("LeishMan ORCID worker v2 is running");
      if (url.pathname === "/auth/orcid") return startAuth(url, env);
      if (url.pathname === "/auth/orcid/callback") return handleCallback(request, url, env);
      return text("Not Found", 404);
    } catch (err) {
      console.error("orcid worker error", err);
      return text("Internal error", 500);
    }
  },
};

function text(body, status = 200) {
  return new Response(body, { status, headers: { "Content-Type": "text/plain; charset=utf-8" } });
}

function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

/** Safe JSON for inlining inside a <script> tag. */
function scriptJson(v) {
  const LS = String.fromCharCode(0x2028);
  const PS = String.fromCharCode(0x2029);
  return JSON.stringify(v).split("<").join("\\u003c").split(LS).join("\\u2028").split(PS).join("\\u2029");
}

function readCookie(request, name) {
  const m = (request.headers.get("Cookie") || "").match(new RegExp(`(?:^|;\\s*)${name}=([^;]+)`));
  return m ? decodeURIComponent(m[1]) : null;
}

/** Step 1: remember where to send the result, then redirect to ORCID. */
function startAuth(url, env) {
  const requested = url.searchParams.get("origin");
  // Older CMS builds do not send `origin`: fall back to the main site.
  const origin = requested && isAllowedOrigin(requested, env.ALLOWED_ORIGINS) ? requested : env.FRONT_URL;
  const mode = url.searchParams.get("mode") === "site" ? "site" : "cms";
  const state = randomId();

  const params = new URLSearchParams({
    client_id: env.ORCID_CLIENT_ID,
    response_type: "code",
    scope: "/authenticate",
    redirect_uri: `${env.BASE_URL}/auth/orcid/callback`,
    state,
  });

  const cookie = encodeURIComponent(JSON.stringify({ state, origin, mode }));
  return new Response(null, {
    status: 302,
    headers: {
      Location: `https://orcid.org/oauth/authorize?${params}`,
      "Set-Cookie": `${STATE_COOKIE}=${cookie}; HttpOnly; Secure; Max-Age=600; Path=/auth/orcid; SameSite=Lax`,
    },
  });
}

/** Step 2: ORCID redirects back here. */
async function handleCallback(request, url, env) {
  let saved = null;
  try {
    saved = JSON.parse(readCookie(request, STATE_COOKIE) || "null");
  } catch {
    saved = null;
  }
  const code = url.searchParams.get("code");
  if (!saved || !saved.state || saved.state !== url.searchParams.get("state")) {
    return page("Login expired", "<p>The login session expired or is invalid. Please close this window and try again.</p>", 400);
  }
  if (!code) return page("Login cancelled", "<p>No authorization code was returned by ORCID.</p>", 400);

  const tokenResponse = await fetch("https://orcid.org/oauth/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
    body: new URLSearchParams({
      client_id: env.ORCID_CLIENT_ID,
      client_secret: env.ORCID_CLIENT_SECRET,
      grant_type: "authorization_code",
      code,
      redirect_uri: `${env.BASE_URL}/auth/orcid/callback`,
    }),
  });
  const tokenData = await tokenResponse.json().catch(() => ({}));
  const orcid = tokenData.orcid;
  if (!orcid) return page("Login failed", "<p>ORCID authentication failed.</p>", 400);

  const user = await findUser(orcid, env);
  const contact = escapeHtml(env.CONTACT_EMAIL || "clea.melenotte@aphp.fr");
  if (!user) {
    return page(
      "You are not registered",
      `<p>Your ORCID iD <code>${escapeHtml(orcid)}</code> is not linked to any LeishMan working group.</p>
       <p>Please ask the website manager to add your ORCID iD to your member page.</p>
       <p class="contact">Contact: <strong>${contact}</strong></p>`,
    );
  }

  const canEdit = user.role === "admin" || user.role === "editor";
  if (saved.mode === "cms" && !canEdit) {
    return page(
      "No editing rights",
      `<p>You are registered as a member of: <strong>${escapeHtml(user.folders.join(", "))}</strong>.</p>
       <p>Group documents are available on the website: open your working group page and click <em>Member login</em>.</p>
       <p><a class="btn" href="${escapeHtml(saved.origin)}/projects" target="_blank" rel="noopener">Go to the working groups</a></p>`,
    );
  }

  const session = await signSession(
    { sub: orcid, fn: user.firstname, ln: user.lastname, role: user.role, folders: user.folders },
    env.SESSION_SECRET,
  );

  // `groups` keeps older front-end builds working (they map group names to folders client-side).
  const legacyGroups = user.folders.includes("*") ? ["Admin", ...KNOWN_FOLDERS] : user.folders;
  const message = {
    backendName: "github",
    token: canEdit ? env.GITHUB_BOT_TOKEN : undefined,
    role: user.role,
    groups: legacyGroups,
    folders: user.folders,
    firstname: user.firstname,
    lastname: user.lastname,
    orcid,
    session,
  };

  return new Response(
    `<!doctype html><meta charset="utf-8"><title>Signing in…</title><p>Signing in…</p>
<script>
  (function () {
    var target = ${scriptJson(saved.origin)};
    if (window.opener) { window.opener.postMessage(${scriptJson(message)}, target); }
    window.close();
  })();
</script>`,
    {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "no-store",
        "Set-Cookie": `${STATE_COOKIE}=; HttpOnly; Secure; Max-Age=0; Path=/auth/orcid; SameSite=Lax`,
      },
    },
  );
}

const KNOWN_FOLDERS = ["Biobanking", "Diagnostic-procedure", "Epidemiology", "LC-treatment", "VL-treatment", "Recommendations"];

/** Look the ORCID iD up in /data/access.json, falling back to the legacy YAML lists. */
async function findUser(orcid, env) {
  const accessUrl = env.ACCESS_URL || `${env.FRONT_URL}/data/access.json`;
  try {
    const r = await fetch(accessUrl, { headers: { "Cache-Control": "no-cache" }, cf: { cacheTtl: 0 } });
    if (r.ok) {
      const data = await r.json();
      const u = data?.users?.[orcid];
      if (u) return { firstname: u.firstname || "", lastname: u.lastname || "", role: u.role || "viewer", folders: u.folders || [] };
      if (data?.version) return null; // access map exists and the user is not in it
    }
  } catch (err) {
    console.warn("access.json unavailable, using legacy lists", err);
  }
  return findLegacyUser(orcid, env);
}

const LEGACY_GROUPS = {
  biobanking: "Biobanking",
  diagnostic: "Diagnostic-procedure",
  "diagnostic-procedure": "Diagnostic-procedure",
  epidemiology: "Epidemiology",
  lc: "LC-treatment",
  "lc-treatment": "LC-treatment",
  lv: "VL-treatment",
  "lv-treatment": "VL-treatment",
  "vl-treatment": "VL-treatment",
  recommendations: "Recommendations",
  admin: "Admin-Files",
};

async function findLegacyUser(orcid, env) {
  for (const role of ["admin", "editor", "viewer"]) {
    const r = await fetch(`${env.FRONT_URL}/data/users/${role}.yml`, { headers: { "Cache-Control": "no-cache" } });
    if (!r.ok) continue;
    for (const u of parseLegacyYaml(await r.text())) {
      if (u.orcid !== orcid) continue;
      const folders = role === "admin" ? ["*"] : u.group.map((g) => LEGACY_GROUPS[g.toLowerCase()] || g);
      return { role, firstname: u.firstname || "", lastname: u.lastname || "", folders };
    }
  }
  return null;
}

/** Minimal parser for the legacy `- lastname: ... group: [- x]` YAML lists. */
function parseLegacyYaml(yamlText) {
  const result = [];
  let cur = null;
  for (let line of yamlText.split("\n")) {
    line = line.trim();
    if (line.startsWith("- lastname:")) {
      if (cur) result.push(cur);
      cur = { group: [] };
      line = line.slice(2);
    }
    if (!cur) continue;
    const kv = line.match(/^(\w+):\s*(.*)$/);
    if (kv) {
      if (kv[1] !== "group") cur[kv[1]] = kv[2].trim().replace(/['"]/g, "");
    } else if (line.startsWith("- ")) {
      cur.group.push(line.slice(2).trim());
    }
  }
  if (cur) result.push(cur);
  return result;
}

function page(title, bodyHtml, status = 200) {
  return new Response(
    `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body{font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;display:flex;justify-content:center;align-items:center;min-height:100vh;margin:0;background:#f1f5f9;color:#0f172a}
  .box{max-width:460px;margin:16px;text-align:center;background:#fff;padding:28px;border-radius:16px;box-shadow:0 10px 30px rgba(15,23,42,.08)}
  h1{font-size:1.3rem} p{color:#334155;line-height:1.5} .contact{font-size:.9rem;color:#64748b}
  .btn{display:inline-block;margin-top:14px;padding:10px 18px;color:#fff;background:#2563eb;border:0;border-radius:999px;text-decoration:none;cursor:pointer}
</style></head>
<body><div class="box"><h1>${escapeHtml(title)}</h1>${bodyHtml}
<button class="btn" onclick="window.close()">Close</button></div></body></html>`,
    { status, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } },
  );
}
